import gurobipy
from gurobipy import GRB

def solve_problem():
    table = CSVQA_DATA['tables'][0]
    records = table['records']
    items = []
    v = {}
    w = {}
    for rec in records:
        vals = rec['values']
        item = vals['item']
        items.append(item)
        v[item] = float(vals['value'])
        w[item] = float(vals['weight'])
    if not items:
        raise ValueError('No items found in data.')
    m = gurobipy.Model()
    m.setParam('MIPGap', 1e-06)
    x = m.addVars(items, vtype=GRB.BINARY, name='')
    m.setObjective(gurobipy.quicksum((v[i] * x[i] for i in items)), GRB.MAXIMIZE)
    m.addConstr(gurobipy.quicksum((w[i] * x[i] for i in items)) <= 15)
    m.optimize()
    return m
m = solve_problem()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
